<script setup>
import {collectAirings} from "./airings.js";
import {dramaCategoryStyle} from './categoryColors.js';
import DramaBulkImport from './DramaBulkImport.vue';
import DramaCastSearch from './DramaCastSearch.vue';
import DramaWeekdaysEditor from './DramaWeekdaysEditor.vue';
import DramaImageGallery from './DramaImageGallery.vue';
import DramaImageEditor from './DramaImageEditor.vue';
import {dramaImages,validateDramaImages} from './images.js';
import {productionCompanyOptions} from './companies.js';
const props=defineProps({scheduleArtists:{type:Array,default:()=>[]},repository:{type:Object,default:null}});

import {resolvePlatformLogo,matchedPlatform,validateNewPlatform} from './platforms.js';
const platformLogo=p=>resolvePlatformLogo(p,import.meta.env.BASE_URL);
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';
import {initialData} from './seed.js';
import {generateSchedule,dramaTitle,dramaTypes,validateDrama,reschedule,announcementsForEpisode} from './schedule.js';
const key='chob-drama-private-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(key));}catch{}
const db=ref(props.repository?{dramas:[],platforms:[],events:[],changes:[],artists:[],drafts:[]}:saved?.dramas && saved?.platforms && saved?.events && saved?.changes && saved?.artists?saved:structuredClone(initialData));
const storageError=ref('');
let loaded=false;onMounted(async()=>{try{if(props.repository){await reloadRemote();loaded=true;return;}const response=await fetch('/__drama_test_data');if(!response.ok)throw Error('测试数据读取失败');db.value=await response.json();await Promise.resolve();loaded=true;if(new URLSearchParams(location.search).has('new'))edit();}catch(e){storageError.value=e.message;}});
watch(db,async()=>{if(!loaded||props.repository)return;try{const response=await fetch('/__drama_test_data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(db.value)});if(!response.ok)throw Error('测试数据保存失败');}catch(e){storageError.value=e.message;return;}try{localStorage.setItem(key,JSON.stringify(db.value));storageError.value='';}catch{storageError.value='无法保存到此浏览器，请导出备份。';}},{deep:true});
const reviewRows=ref([]),reviewError=ref(''),activeReview=ref(null),scheduleEvents=ref([]);
async function loadReviews(){try{reviewRows.value=await props.repository.submissions();reviewError.value='';}catch(e){reviewError.value=e.message;}}
async function openReview(row){const data=row.kind==='addition'?{...row.payload,id:crypto.randomUUID()}:db.value.dramas.find(d=>d.id===row.series_id);if(!data){reviewError.value='关联剧集已归档或不存在，请先核对';return;}edit(data);activeReview.value=row;editing.value._reviewId=row.id;savedEditorSnapshot.value=JSON.stringify(editing.value);}
async function rejectReview(row){if(!window.confirm('确认拒绝这条剧集投稿？'))return;try{await props.repository.review(row.id,'rejected');await loadReviews();}catch(e){reviewError.value=e.message;}}
onMounted(async()=>{if(props.repository){await loadReviews();try{scheduleEvents.value=await props.repository.scheduleEvents();}catch(e){storageError.value=e.message;}}});
const tourEditing=ref(null);
function editTour(item){tourEditing.value=structuredClone(JSON.parse(JSON.stringify(item)));tourEditing.value.stops||=[{time:item.time,content:item.name,location:item.location}];tourEditing.value.images||=[];}
async function saveTour(){if(busy.value)return;busy.value=true;try{const item=tourEditing.value;if(!item.name?.trim()||!item.date)throw Error('请填写活动名称与日期');if(!item.stops.length||item.stops.some(s=>!s.time||!s.content?.trim()))throw Error('每站请填写时间与内容');validateDramaImages(item);item.stops.sort((a,b)=>a.time.localeCompare(b.time));item.time=item.stops[0].time;item.location=item.stops[0].location;if(props.repository){await props.repository.saveEvent(item);await reloadRemote();}else{const i=db.value.events.findIndex(e=>e.id===item.id);if(i>=0)db.value.events[i]=item;else db.value.events.push(item);}tourEditing.value=null;}catch(e){storageError.value=e.message;}finally{busy.value=false;}}
const tab=ref('library'),month=ref('2026-11'),search=ref(''),selected=ref(null),editing=ref(null),error=ref(''),notice=ref(''),eventSelected=ref(null),changeSlot=ref(null);
const closeEditorPrompt=ref(false),savedEditorSnapshot=ref('');
const editorDirty=computed(()=>Boolean(editing.value)&&JSON.stringify(editing.value)!==savedEditorSnapshot.value);
function requestEditorClose(){if(busy.value)return;if(!editorDirty.value){closeEditorPrompt.value=false;editing.value=null;return;}closeEditorPrompt.value=true;}
async function closeWithDraft(){if(await saveDraft()){closeEditorPrompt.value=false;editing.value=null;}}
async function closeWithSave(){await save();if(!editing.value)closeEditorPrompt.value=false;}
function discardEditor(){if(busy.value)return;closeEditorPrompt.value=false;editing.value=null;}
function protectEditorKey(event){if(event.key==='Escape'&&editing.value){event.preventDefault();if(closeEditorPrompt.value)closeEditorPrompt.value=false;else requestEditorClose();}}
function protectEditorUnload(event){if(editorDirty.value){event.preventDefault();event.returnValue='';}}
onMounted(()=>{document.addEventListener('keydown',protectEditorKey);window.addEventListener('beforeunload',protectEditorUnload);});onBeforeUnmount(()=>{document.removeEventListener('keydown',protectEditorKey);window.removeEventListener('beforeunload',protectEditorUnload);});
const changeForm=ref({date:'',time:'',content:''});
const title=dramaTitle;
function safe(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
const listCompany=ref(''),listType=ref(''),listProduction=ref(''),listBroadcast=ref(''),showImport=ref(false);
const listCompanies=computed(()=>[...new Set(db.value.dramas.map(d=>d.productionCompany).filter(Boolean))].sort());
function resetListFilters(){search.value='';listCompany.value='';listType.value='';listProduction.value='';listBroadcast.value='';}
async function imported(){if(props.repository)await reloadRemote();}
const filtered=computed(()=>db.value.dramas.filter(d=>(!listCompany.value||d.productionCompany===listCompany.value)&&(!listType.value||d.types.includes(listType.value))&&(!listProduction.value||d.production===listProduction.value)&&(!listBroadcast.value||(listBroadcast.value==='未定档'?!d.rules.some(r=>r.premiere):status(d)===listBroadcast.value))).filter(d=>[d.titleZh,d.titleEn,d.titleTh,d.productionCompany,...d.cast.map(c=>c.name),...d.types].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const page=ref(1),selection=ref([]);const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/30)));const pageRows=computed(()=>filtered.value.slice((page.value-1)*30,page.value*30));watch(filtered,()=>{page.value=Math.min(page.value,pages.value);selection.value=selection.value.filter(id=>filtered.value.some(d=>d.id===id));});
async function removeDraft(draft){if(busy.value||!window.confirm('确认删除草稿“'+(title(draft)||'未命名草稿')+'”？此操作只删除草稿。'))return;busy.value=true;try{if(props.repository){await props.repository.deleteDraft(draft.id);await reloadRemote();}else db.value.drafts=(db.value.drafts||[]).filter(d=>d.id!==draft.id);}catch(e){storageError.value=e.message;}finally{busy.value=false;}}
async function archiveRows(ids){if(!ids.length||busy.value||!window.confirm('确认删除所选 '+ids.length+' 部剧集？资料将归档保留，不再展示。'))return;busy.value=true;try{if(props.repository){await props.repository.archive(ids);await reloadRemote();}else db.value.dramas=db.value.dramas.filter(d=>!ids.includes(d.id));selection.value=[];}catch(e){storageError.value=e.message;}finally{busy.value=false;}}
const airingResult=computed(()=>collectAirings(db.value.dramas,db.value.changes));
const slots=computed(()=>airingResult.value.slots);
const days=computed(()=>{if(!month.value)return [];const start=new Date(month.value+'-01T00:00:00Z');const count=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0)).getUTCDate();return [...Array((start.getUTCDay()+6)%7).fill(null),...Array.from({length:count},(_,i)=>`${month.value}-${String(i+1).padStart(2,'0')}`)];});
const notices=computed(()=>selected.value?.slot?announcementsForEpisode(db.value.changes.map(c=>c.announcement),selected.value.drama.id,selected.value.slot.episode):db.value.changes.filter(c=>c.announcement.dramaId===selected.value?.drama.id).map(c=>c.announcement));
function drama(id){return db.value.dramas.find(d=>d.id===id);}
function platform(id){return db.value.platforms.find(p=>p.id===id)||{name:id};}
function status(d){const rows=slots.value.filter(s=>s.dramaId===d.id&&s.status!=='changed');if(!rows.length)return d.production;if(rows.every(s=>s.date<new Date().toISOString().slice(0,10)))return '已完播';return rows.some(s=>s.date<=new Date().toISOString().slice(0,10))?'播出中':'待播';}
function open(d,slot=null){selected.value={drama:d,slot};}
function edit(d){activeReview.value=null;if(props.repository&&!loaded){storageError.value='资料还在加载，请稍后重试';return;}let draft;try{if(!props.repository)draft=JSON.parse(localStorage.getItem('chob-admin-drama-draft'));}catch{}editing.value=JSON.parse(JSON.stringify(d||draft||{id:crypto.randomUUID(),titleZh:'',titleEn:'',titleTh:'',types:[],production:'',poster:'',synopsis:'',cast:[],rules:[]}));activeReview.value=editing.value._reviewId?reviewRows.value.find(r=>r.id===editing.value._reviewId)||null:null;savedEditorSnapshot.value=JSON.stringify(editing.value);error.value='';}
function addRule(){editing.value.rules.push({id:crypto.randomUUID(),platformId:'youtube',premiere:'',totalEpisodes:12,weekdays:[],phases:[],episodesPerRelease:1,time:'21:30',timezone:'Asia/Bangkok'});}
async function save(){if(busy.value)return;busy.value=true;try{if(editing.value._reviewId&&!activeReview.value)throw Error('原投稿可能已处理，请刷新审核队列后核对，不能重复保存为新剧集');validateDrama(editing.value);validateDramaImages(editing.value);if(editing.value.cast.some(c=>!c.artistId))throw Error('请从匹配结果中选择卡司艺人，或移除未填写的卡司行');if(props.repository){if(activeReview.value){await props.repository.review(activeReview.value.id,'approved',editing.value);activeReview.value=null;await loadReviews();}else{const savedRow=await props.repository.save(editing.value);editing.value._version=savedRow.version;}const draftId=editing.value.id;try{await props.repository.deleteDraft(draftId);}catch{notice.value='剧集已保存，但旧草稿未清除，可稍后处理';}await reloadRemote();editing.value=null;notice.value='已保存到 Supabase，排播已生成；内容仍为私有';return;}for(const r of editing.value.rules)generateSchedule(editing.value,r);const old=db.value.dramas.find(d=>d.id===editing.value.id);if(old&&db.value.changes.some(c=>c.original.dramaId===old.id)&&JSON.stringify(old.rules)!==JSON.stringify(editing.value.rules))throw Error('已有变动历史，请通过单集变动调整排期，保留原始记录。');const i=db.value.dramas.findIndex(d=>d.id===editing.value.id);if(i<0)db.value.dramas.push(editing.value);else db.value.dramas[i]=editing.value;localStorage.removeItem('chob-admin-drama-draft');editing.value=null;notice.value='已保存到隔离测试数据';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function saveDraft(){if(busy.value)return;busy.value=true;const snapshot=JSON.stringify(editing.value);try{if(props.repository){await props.repository.saveDraft(JSON.parse(snapshot));savedEditorSnapshot.value=snapshot;await reloadRemote();error.value='草稿已存入 Supabase，未排播';}else{localStorage.setItem('chob-admin-drama-draft',snapshot);savedEditorSnapshot.value=snapshot;error.value='草稿已保存在当前浏览器，未排播';}return true;}catch(e){error.value=e.message;return false;}finally{busy.value=false;}}
async function applyChange(){if(busy.value)return;busy.value=true;try{if(props.repository){const d=db.value.dramas.find(d=>d.id===changeSlot.value.dramaId);await props.repository.change(changeSlot.value,changeForm.value,d._version);await reloadRemote();}else{db.value.changes.push(reschedule(changeSlot.value,changeForm.value,{id:crypto.randomUUID(),content:changeForm.value.content}));}changeSlot.value=null;selected.value=null;}catch(e){error.value=e.message;}finally{busy.value=false;}}
function change(s){changeSlot.value=s;changeForm.value={date:s.date,time:s.time,content:''};error.value='';}
function addCast(){const artist=db.value.artists[0];if(!artist){error.value='艺人资料正在加载或无可用艺人';return;}editing.value.cast.push({artistId:'',name:'',role:'',lead:false});}
function exportData(){const url=URL.createObjectURL(new Blob([JSON.stringify(db.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='chob-drama-test-backup.json';a.click();URL.revokeObjectURL(url);}
async function addEvent(event){if(busy.value)return;busy.value=true;try{const fields=event.target.elements;const item={id:crypto.randomUUID(),name:fields.eventName.value,date:fields.eventDate.value,time:fields.eventTime.value,dramaId:fields.dramaId.value,type:fields.eventType.value,region:fields.eventRegion.value,location:fields.eventLocation.value};if(props.repository){await props.repository.saveEvent(item);await reloadRemote();}else db.value.events.push(item);event.target.reset();}catch(e){storageError.value=e.message;}finally{busy.value=false;}}
const companyChoices=computed(()=>productionCompanyOptions(props.scheduleArtists.length?props.scheduleArtists:db.value.artists,editing.value?.productionCompany||''));
const busy=ref(false);
async function reloadRemote(){db.value=await props.repository.load();db.value.artists=props.scheduleArtists.filter(a=>!a.deleted_at);}
watch(()=>props.scheduleArtists,artists=>{if(props.repository)db.value.artists=artists.filter(a=>!a.deleted_at);});
async function savePlatform(p){if(!props.repository)return;try{await props.repository.savePlatform({id:p.id,name:p.name,logo:p.logo});notice.value='平台配置已保存';}catch(e){storageError.value=e.message;}}
let previousBodyOverflow;
watch(()=>Boolean(editing.value||selected.value||changeSlot.value||eventSelected.value||tourEditing.value),open=>{if(open){previousBodyOverflow??=document.body.style.overflow;document.body.style.overflow='hidden';}else if(previousBodyOverflow!==undefined){document.body.style.overflow=previousBodyOverflow;previousBodyOverflow=undefined;}});
onBeforeUnmount(()=>{if(previousBodyOverflow!==undefined)document.body.style.overflow=previousBodyOverflow;});
function setImages(images){editing.value.images=images;editing.value.poster=images.find(url=>url.trim())||'';}
const platformForm=ref({name:'',logo:''}),platformError=ref(''),platformSaving=ref(false);
async function addPlatform(){if(platformSaving.value)return;platformError.value='';platformSaving.value=true;try{const fields=validateNewPlatform(platformForm.value.name,platformForm.value.logo,db.value.platforms);const platform={id:crypto.randomUUID(),...fields};if(props.repository)await props.repository.createPlatform(platform);db.value.platforms.push(platform);platformForm.value={name:'',logo:''};notice.value=props.repository?'平台已保存到云端，可在剧集排期中选择':'平台已保存，可在剧集排期中选择';}catch(e){platformError.value=e.message;}finally{platformSaving.value=false;}}
</script>
<template>
<div class="shell"><header><a class="brand" href="#">CHOB<span>CALENDAR</span></a><span class="private">{{repository?'管理员私有录入 · Supabase':'后台管理 · 隔离测试数据'}}</span><button @click="exportData">导出备份</button></header>
<main><aside v-if="airingResult.errors.length" class="error" role="alert"><p>部分平台排期需要修正，其他剧集仍可正常管理。请编辑对应剧集核对：</p><p v-for="issue in airingResult.errors" :key="issue.dramaId+issue.ruleId">{{issue.message}}</p></aside><div class="heading"><div><p class="eyebrow">STORIES, ONE DAY AT A TIME</p><h1>Drama <em>剧集管理</em></h1><p class="muted">把每一次相遇，放进日历。</p></div><button class="primary" @click="edit()">＋ 录入剧集</button></div>
<nav><button v-for="(label,id) in {library:'剧集管理',events:'关联活动管理',platforms:'平台管理',review:'剧集投稿审核'}" :class="{active:tab===id}" @click="tab=id">{{label}}</button></nav>
<p v-if="storageError" role="alert">{{storageError}}</p><p v-if="notice" role="status">{{notice}}</p><section v-if="tab==='review'" class="drama-review"><h2>剧集投稿与纠错</h2><p>独立于 Schedule 活动审核。通过后只更新私有剧集资料，不公开 Drama。</p><button v-if="repository" @click="loadReviews">刷新审核队列</button><p v-if="reviewError" role="alert">{{reviewError}}</p><p v-if="!reviewError&&!reviewRows.length">暂无待审核投稿</p><article class="panel" v-for="row in reviewRows" :key="row.id"><small>{{row.kind==='addition'?'新增剧集':'剧集纠错'}} · {{row.created_at.slice(0,10)}}</small><h3>{{row.kind==='addition'?title(row.payload):title(drama(row.series_id)||{})}}</h3><p v-if="row.kind==='correction'">{{row.payload.message}}</p><button @click="openReview(row)">编辑并审核</button><button @click="rejectReview(row)">拒绝</button></article><small v-if="reviewRows.length===100">显示最早 100 条待审核内容，处理后刷新可继续查看。</small></section><section v-if="tab==='library'&&db.drafts?.length" class="draft-section"><h3>云端草稿</h3><article class="draft-row" v-for="draft in db.drafts" :key="draft.id"><span>{{title(draft)||'未命名草稿'}}</span><div><button @click="edit(draft)">编辑</button><button class="danger-action" :disabled="busy" @click="removeDraft(draft)">删除</button></div></article></section>
<section v-if="tab==='calendar'"><div class="toolbar"><input type="month" v-model="month" aria-label="月份"><span class="muted">平台当地时间 · 推算排期有单独标记</span></div><div class="calendar"><b v-for="w in ['一','二','三','四','五','六','日']" class="weekday">{{w}}</b><div v-for="(day,index) in days" :key="day||index" class="day" :class="{blank:!day}"><span class="day-number">{{day?Number(day.slice(-2)):''}}</span><template v-if="day"><button v-for="s in slots.filter(s=>s.date===day)" :key="s.id" class="chip" :class="{changed:s.status==='changed'}" @click="open(drama(s.dramaId),s)"><span :class="{strike:s.status==='changed'}">{{title(drama(s.dramaId))}} · EP.{{s.episode}}</span><small>{{s.status==='changed'?'剧集变动':`${s.time} · ${platform(s.platformId).name}`}}{{s.confidence==='calculated'?' · 推算':''}}</small></button><button v-for="e in db.events.filter(e=>e.date===day)" class="chip event" @click="eventSelected=e">{{e.type}}<small>{{e.name}}</small></button></template></div></div></section>
<section v-if="tab==='library'"><div class="list-filters"><label>出品公司<select v-model="listCompany"><option value="">全部公司</option><option v-for="company in listCompanies" :value="company">{{company}}</option></select></label><label>剧集类别<select v-model="listType"><option value="">全部类别</option><option v-for="type in dramaTypes" :value="type">{{type}}</option></select></label><label>制作进度<select v-model="listProduction"><option value="">全部进度</option><option>已公布</option><option>未开机</option><option>已开机</option><option>已杀青</option></select></label><label>播出状态<select v-model="listBroadcast"><option value="">全部状态</option><option>未定档</option><option>待播</option><option>播出中</option><option>已完播</option></select></label><button @click="resetListFilters">重置筛选</button><button @click="showImport=!showImport">{{showImport?'收起批量导入':'批量导入 / 下载模板'}}</button></div><DramaBulkImport v-if="showImport" :repository="repository" :catalog="db" @refresh="imported" /><div class="toolbar"><input v-model="search" placeholder="搜索剧名、卡司、公司、类型" aria-label="搜索剧集"><span>{{filtered.length}} 部剧集</span></div><div class="bulk-actions" v-if="tab==='library'"><button @click="selection=pageRows.map(d=>d.id)">选择本页</button><button @click="selection=[]">取消选择</button><button :disabled="!selection.length||busy" @click="archiveRows(selection)">批量删除（{{selection.length}}）</button></div><div class="cards"><article v-for="d in pageRows" :key="d.id" class="card" :style="dramaCategoryStyle(d.types)"><button class="card-main" @click="open(d)"><img v-if="dramaImages(d)[0]" :src="dramaImages(d)[0]" alt="剧集海报"><div v-else class="poster">CHOB<br>DRAMA</div><div><span class="badge">{{status(d)}}</span><h2>{{title(d)}}</h2><p>{{d.titleEn}}</p><p class="muted">{{d.types.join(' · ')}}</p><p>主演：{{d.cast.filter(c=>c.lead).map(c=>c.name).join('、')||'待公布'}}</p></div></button><div class="card-actions"><label><input type="checkbox" v-model="selection" :value="d.id">选择</label><button @click="edit(d)">编辑</button><button class="danger-action" @click="archiveRows([d.id])">删除</button></div></article></div><p v-if="!filtered.length">暂无匹配剧集</p></section>
<nav v-if="tab==='library'" class="pagination"><button :disabled="page<=1" @click="page--">上一页</button><label class="page-entry"><input aria-label="跳转页码" type="number" min="1" :max="pages" :value="page" @change="page=Math.min(pages,Math.max(1,Math.trunc(Number($event.target.value)||1)));$event.target.value=page" @keydown.enter.prevent="$event.target.blur()"> / {{pages}} · 每页30部</label><button :disabled="page>=pages" @click="page++">下一页</button></nav><section class="change-board" v-if="tab==='library'"><h3>排播变动公告</h3><p v-if="!db.changes.length">暂无排播变动公告</p><article v-for="change in db.changes" :key="change.announcement.id"><strong>{{title(drama(change.announcement.dramaId)||{})}}</strong><p>{{change.announcement.content}}</p><small>{{change.announcement.originalDate}} → {{change.announcement.updatedDate}}</small></article></section><section v-if="tab==='events'"><button @click="editTour({id:crypto.randomUUID(),name:'',date:'',dramaId:db.dramas[0]?.id,type:'Press Tour',region:'thailand',stops:[{time:'',content:'',location:''}],images:[]})">＋ 新增多站活动</button><h2>Calendar · 关联活动</h2><p class="muted">这里展示隔离的活动资料，可从活动返回剧集详情。</p><article class="event-row" v-for="e in db.events"><span>{{e.date}} {{e.time}}</span><button @click="eventSelected=e">{{e.name}}</button><button @click="editTour(e)">编辑活动</button><button @click="open(drama(e.dramaId))">查看关联剧集</button></article><form class="panel" @submit.prevent="addEvent($event)"><h3>新增关联活动</h3><input name="eventName" required placeholder="活动名称"><input name="eventDate" type="date" required><input name="eventTime" type="time" required><select name="eventRegion"><option value="thailand">泰国</option><option value="oversea">海外</option></select><input name="eventLocation" placeholder="地点"><select name="eventType"><option>Press Tour</option><option>观影活动</option><option>首映礼</option></select><select name="dramaId" required><option v-for="d in db.dramas" :value="d.id">{{title(d)}}</option></select><button class="primary">保存活动</button></form></section>
<section v-if="tab==='platforms'"><h2>平台管理</h2><form class="platform-create" @submit.prevent="addPlatform"><h3>新增平台</h3><div class="platform-create-fields"><label>平台名称<input v-model="platformForm.name" placeholder="例如 WeTV、one31、Netflix" maxlength="100" required></label><label>Logo 图片链接（可留空）<input v-model="platformForm.logo" type="url" placeholder="https://…"></label><button class="primary" :disabled="platformSaving">{{platformSaving?'正在保存…':'＋ 新增平台'}}</button></div><p>只填写名称也可以新增；识别到的平台自动配图标，其他平台先显示文字。</p><p v-if="platformError" class="error" role="alert">{{platformError}}</p></form><h3>已有平台</h3><div class="event-row" v-for="p in db.platforms"><label>名称<input v-model="p.name" @change="savePlatform(p)"></label><label>自定义 Logo（可留空）<input v-model="p.logo" @change="savePlatform(p)" type="url" placeholder="留空自动匹配"></label><span class="platform"><img v-if="platformLogo(p)" :src="platformLogo(p)" alt="">{{p.name}}</span><small>{{p.logo?'使用自定义图片':matchedPlatform(p)?'已自动匹配':'未识别，暂显示文字'}}</small><button v-if="p.logo" @click="p.logo='';savePlatform(p)">恢复自动匹配</button></div><p class="muted">YouTube、爱奇艺可按名称自动匹配官方站点图标；自定义链接可覆盖。图标高 16px，保持原始比例。</p></section>
</main>
<Teleport to="body"><div v-if="closeEditorPrompt" class="overlay editor-close-overlay"><section class="dialog editor-close-dialog" role="alertdialog" aria-modal="true" aria-label="关闭前保存剧集"><h2>关闭前如何处理这份资料？</h2><p>可以保存并生成排期，也可以存草稿后继续填写。</p><p v-if="error" class="error" role="alert">{{error}}</p><div class="close-editor-actions"><button class="primary" :disabled="busy" @click="closeWithSave">发布并关闭</button><button :disabled="busy" @click="closeWithDraft">存草稿并关闭</button><button :disabled="busy" @click="discardEditor">取消保存并离开</button><button :disabled="busy" @click="closeEditorPrompt=false">继续编辑</button></div></section></div><div v-if="tourEditing" class="overlay"><form class="dialog editor" @submit.prevent="saveTour"><button type="button" class="close" @click="tourEditing=null">取消 ×</button><h2>编辑关联活动</h2><label v-if="repository">关联 Schedule 活动<select v-model="tourEditing.eventId"><option :value="null">暂不关联</option><option v-for="event in scheduleEvents" :key="event.id" :value="event.id">{{event.date}} · {{event.title}} · {{event.status==='published'?'已发布':'草稿'}}</option></select><small>这里只建立关联，不改变 Schedule 活动内容或发布状态。最近 500 条活动可选。</small></label><label>活动名称<input v-model="tourEditing.name" required></label><label>日期<input type="date" v-model="tourEditing.date" required></label><label>关联剧集<select v-model="tourEditing.dramaId" required><option v-for="d in db.dramas" :value="d.id">{{title(d)}}</option></select></label><label>地区<select v-model="tourEditing.region"><option value="thailand">泰国</option><option value="oversea">海外</option></select></label><DramaImageEditor :model-value="tourEditing.images" @update:model-value="value=>tourEditing.images=value"/><h3>当天行程 · 按时间填写</h3><div class="panel" v-for="(stop,i) in tourEditing.stops"><label>时间<input type="time" v-model="stop.time" required></label><label>内容<input v-model="stop.content" required></label><label>地点<input v-model="stop.location"></label><button type="button" @click="tourEditing.stops.splice(i,1)">移除此站</button></div><button type="button" @click="tourEditing.stops.push({time:'',content:'',location:''})">＋ 当天活动</button><p role="alert">{{storageError}}</p><button class="primary" :disabled="busy">保存关联活动</button></form></div><div v-if="selected" class="overlay" @click.self="selected=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="剧集详情" tabindex="-1" @keydown.esc="selected=null"><button class="close" @click="selected=null">关闭 ×</button><div class="hero"><DramaImageGallery :drama="selected.drama" /><div v-if="selected.slot?.status==='changed'" class="banner"><strong>剧集变动</strong><span>{{notices.find(n=>n.id===selected.slot.announcementId)?.content}}</span></div></div><span class="badge">{{status(selected.drama)}}</span><h2>{{title(selected.drama)}}</h2><p>{{selected.drama.types.join(' · ')}}</p><p>{{selected.drama.synopsis}}</p><h3 v-if="selected.slot">EP.{{selected.slot.episode}} · {{selected.slot.date}}</h3><p v-if="selected.slot" class="platform"><img v-if="platformLogo(platform(selected.slot.platformId))" :src="platformLogo(platform(selected.slot.platformId))" alt="">{{platform(selected.slot.platformId).name}} · {{selected.slot.time}} · {{selected.slot.timezone}} <small>{{selected.slot.confidence==='calculated'?'系统推算':'已确认'}}</small></p><button v-if="selected.slot?.status==='scheduled'" @click="change(selected.slot)">调整本集排播</button><aside v-for="n in notices" class="announcement"><strong>剧集变动 · EP.{{n.affectedEpisodes.join('、')}}</strong><p>{{n.content}}</p><small>原定 {{n.originalDate}} → 调整后 {{n.updatedDate}}</small></aside><h3>卡司与角色</h3><p v-for="c in selected.drama.cast">{{c.name}} 饰 {{c.role||'待公布'}} {{c.lead?'· 主演':''}}</p><a v-if="safe(selected.drama.source)" :href="safe(selected.drama.source)" target="_blank" rel="noopener noreferrer">官方来源</a><h3>Press Tour / 观影活动</h3><button v-for="e in db.events.filter(e=>e.dramaId===selected.drama.id)" class="event-row" @click="eventSelected=e">{{e.date}} · {{e.name}} Calendar</button></section></div>
<div v-if="editing" class="overlay" @click.self="requestEditorClose"><form class="dialog editor" @submit.prevent="save"><button type="button" class="close" @click="requestEditorClose">取消 ×</button><h2>剧集录入</h2><p class="muted">三种剧名至少填写一项；没有明确首播日期时只进入剧集库。</p><aside v-if="activeReview" class="panel"><strong>审核资料</strong><p>{{activeReview.kind==='correction'?activeReview.payload.message:'核对新增剧集后保存，即通过审核；不会公开。'}}</p></aside><label v-for="(label,k) in {titleZh:'中文名',titleEn:'英文名',titleTh:'泰语名',source:'官方来源链接'}">{{label}}<input v-model="editing[k]"></label><DramaImageEditor :model-value="editing.images||(dramaImages(editing).length?dramaImages(editing):[''])" @update:model-value="setImages" /><label>出品公司<select v-model="editing.productionCompany"><option :value="undefined">请选择出品公司</option><option value="">待公布</option><option v-for="company in companyChoices" :key="company" :value="company">{{company}}</option></select><small v-if="!companyChoices.length">暂无公司资料，载入 Schedule 艺人资料库后可选择。</small></label><label>简介<textarea v-model="editing.synopsis"></textarea></label><fieldset><legend>类型</legend><div class="type-grid"><label v-for="t in dramaTypes" class="inline"><input type="checkbox" v-model="editing.types" :value="t">{{t}}</label></div></fieldset><label>制作进度<select v-model="editing.production"><option value="">未填写（不展示）</option><option>已公布</option><option>未开机</option><option>已开机</option><option>已杀青</option></select></label><h3>卡司</h3><div class="panel" v-for="(c,i) in editing.cast"><DramaCastSearch :model-value="c.artistId" :fallback-name="c.name" :artists="db.artists" @select="artist=>{c.artistId=artist?.id||'';c.name=artist?.en_name||artist?.name||''}" /><input v-model="c.role" placeholder="角色名称"><label class="inline"><input type="checkbox" v-model="c.lead">主演</label><button type="button" @click="editing.cast.splice(i,1)">移除</button></div><button type="button" @click="addCast">＋ 卡司</button><h3>播出安排</h3><div class="panel" v-for="(r,i) in editing.rules"><label>平台<select v-model="r.platformId"><option v-for="p in db.platforms" :value="p.id">{{p.name}}</option></select></label><label>首播日期<input type="date" v-model="r.premiere"></label><label>总集数<label class="inline"><input type="checkbox" v-model="r.totalEpisodesUnknown" @change="r.totalEpisodes=r.totalEpisodesUnknown?null:12">未知</label><input :disabled="r.totalEpisodesUnknown" :placeholder="r.totalEpisodesUnknown?'未知':'请输入总集数'" type="number" min="1" max="1000" v-model.number="r.totalEpisodes"></label><DramaWeekdaysEditor v-model="editing.rules[i]" /><label>每次更新集数<input type="number" min="1" max="1000" v-model.number="r.episodesPerRelease"></label><label>播出时间<input type="time" v-model="r.time"></label><label>时区<select v-model="r.timezone"><option>Asia/Bangkok</option><option>Asia/Shanghai</option><option>UTC</option></select></label><button type="button" @click="editing.rules.splice(i,1)">移除此平台排期</button></div><div class="rule-add-row"><button type="button" @click="addRule">＋ 平台排期</button></div><p v-if="error" role="alert" class="error">{{error}}</p><div class="form-actions"><button type="button" :disabled="busy" @click="saveDraft">存草稿</button><button class="primary" :disabled="busy">{{busy?'正在保存…':'保存并自动排播'}}</button></div></form></div>
<div v-if="changeSlot" class="overlay"><form class="dialog editor" @submit.prevent="applyChange"><button type="button" class="close" @click="changeSlot=null">取消 ×</button><h2>调整 EP.{{changeSlot.episode}}</h2><p>原日期记录将保留并划线，公告显示在本集及前后集。</p><label>新日期<input type="date" v-model="changeForm.date" required></label><label>新时间<input type="time" v-model="changeForm.time" required></label><label>变动说明<textarea v-model="changeForm.content" required></textarea></label><p class="error" role="alert">{{error}}</p><button class="primary">保存变动公告</button></form></div>
<div v-if="eventSelected" class="overlay" @click.self="eventSelected=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="Calendar 活动详情"><button class="close" @click="eventSelected=null">关闭 ×</button><p class="eyebrow">CALENDAR · {{eventSelected.type}}</p><h2>{{eventSelected.name}}</h2><p>{{eventSelected.date}} {{eventSelected.time}}</p><p>{{eventSelected.location}}</p><button @click="open(drama(eventSelected.dramaId));eventSelected=null">查看关联剧集</button></section></div>
</Teleport><footer>CHOB CALENDAR · DRAMA V1 <span>{{repository?'管理员私有资料 · 未公开':'隔离预览 / 非正式数据'}}</span></footer></div>
